-- 0018_transfer_reopen: a sent transfer request taken back for editing keeps its number (ADR-0046),
-- so a REQUEST draft may carry one; every other draft still has none. Generated by
-- `pnpm db:generate --name=transfer_reopen`. Applied migrations are never edited.
ALTER TABLE "transfers" DROP CONSTRAINT "transfers_number";--> statement-breakpoint
ALTER TABLE "transfers" ADD CONSTRAINT "transfers_number" CHECK (("transfers"."status" <> 'DRAFT' OR "transfers"."number" IS NULL OR "transfers"."origin" = 'REQUEST')
        AND ("transfers"."status" NOT IN ('REQUESTED', 'SHIPPED', 'RECEIVED') OR "transfers"."number" IS NOT NULL));